def normalize_sentinel_incident(incident):
    props = incident["properties"]
    ips = {e["properties"]["address"]
           for e in props["relatedEntities"]
           if e["kind"] == "Ip"}
    return {"source": "sentinel", "id": incident["name"],
            "severity": props["severity"], "ips": ips}

def normalize_asff_finding(finding):
    ips = {ip for r in finding.get("Resources", [])
           for ip in r["Details"].get("AwsEc2Instance", {})
               .get("IpV4Addresses", [])}
    return {"source": "security_hub", "id": finding["Id"],
            "severity": finding["Severity"]["Label"], "ips": ips}

def correlate(sentinel_items, aws_items):
    matches = []
    for s in sentinel_items:
        for a in aws_items:
            shared = s["ips"] & a["ips"]
            if shared:
                matches.append({
                    "sentinel_incident": s["id"],
                    "security_hub_finding": a["id"],
                    "shared_ips": sorted(shared),
                })
    return matches

